    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Conversion conversions:
                Conversions ??= [];
                if (!Conversions.Contains(conversions))
                {
                    Conversions = [..Conversions, conversions];
                    ModifiedParameters[nameof(Conversions)] = Conversions;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case Symbol locationSymbol:
                if (locationSymbol != LocationSymbol)
                {
                    LocationSymbol = locationSymbol;
                    ModifiedParameters[nameof(LocationSymbol)] = LocationSymbol;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case Orientation orientation:
                if (orientation != Orientation)
                {
                    Orientation = orientation;
                    ModifiedParameters[nameof(Orientation)] = Orientation;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case CoordinateConversionVisibleElements visibleElements:
                if (visibleElements != VisibleElements)
                {
                    VisibleElements = visibleElements;
                    ModifiedParameters[nameof(VisibleElements)] = VisibleElements;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Conversion conversions:
                Conversions = Conversions?.Where(c => c != conversions).ToList();
                ModifiedParameters[nameof(Conversions)] = Conversions;
                return true;
            case Symbol _:
                LocationSymbol = null;
                ModifiedParameters[nameof(LocationSymbol)] = LocationSymbol;
                return true;
            case Orientation _:
                Orientation = null;
                ModifiedParameters[nameof(Orientation)] = Orientation;
                return true;
            case CoordinateConversionVisibleElements _:
                VisibleElements = null;
                ModifiedParameters[nameof(VisibleElements)] = VisibleElements;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        if (Conversions is not null)
        {
            foreach (Conversion child in Conversions)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        LocationSymbol?.ValidateRequiredGeneratedChildren();
        Orientation?.ValidateRequiredGeneratedChildren();
        VisibleElements?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
